parameters.command:
\
uip maestro flow node configure "QueryParamsTest.flow" "listAllGoogleTasksInclHidden1" \
  --detail '{
    "authentication": "manual",
    "method": "GET",
    "url": "https://tasks.googleapis.com/tasks/v1/lists/@default/tasks",
    "query": {
      "showHidden": "true",
      "showCompleted": "true"
    },
    "headers": {
      "Authorization": "=js:`Bearer ${$vars.googleAccessToken}`"
    }
  }' --output json && \
uip maestro flow validate "QueryParamsTest.flow" --output json && \
uip maestro flow format "QueryParamsTest.flow" --output json

